package com.lbos.commercecustomer.service;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.client.PartnerVerificationClient;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.enums.ProductStatus;import com.lbos.commercecustomer.exception.ResourceNotFoundException;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.ProductRepository;import com.lbos.commercecustomer.service.impl.FeignCallSupport;import com.lbos.commercecustomer.service.impl.ProductDiscoveryServiceImpl;import com.lbos.commercecustomer.service.impl.RetailerEnrichmentSupport;import java.util.*;import org.junit.jupiter.api.Test;class ProductDiscoveryServiceImplTest{private static RetailerEnrichmentSupport noRetailerEnrichment(){return new RetailerEnrichmentSupport(mock(PartnerVerificationClient.class),new FeignCallSupport());}@Test void activeProductReturned(){var r=mock(ProductRepository.class);var p=new Product();p.setId(1L);p.setStatus(ProductStatus.ACTIVE);p.setRetailerId(UUID.randomUUID());var cat=new ProductCategory();cat.setId(1L);p.setCategory(cat);when(r.findById(1L)).thenReturn(Optional.of(p));
    // get() hides products of a retailer that is not open for orders - S2 must report this one as open.
    var partner=mock(PartnerVerificationClient.class);when(partner.openRetailerIds()).thenReturn(List.of(p.getRetailerId()));
    assertEquals(1L,new ProductDiscoveryServiceImpl(r,new CommerceMapper(),new RetailerEnrichmentSupport(partner,new FeignCallSupport())).get(1L).id());}@Test void draftHidden(){var r=mock(ProductRepository.class);var p=new Product();p.setStatus(ProductStatus.DRAFT);when(r.findById(1L)).thenReturn(Optional.of(p));assertThrows(ResourceNotFoundException.class,()->new ProductDiscoveryServiceImpl(r,new CommerceMapper(),noRetailerEnrichment()).get(1L));}}